########## digest-config.mjs ##########
// The fleet-digest knobs — this repo's reader for the `digest` block on its own
// `sheepdog` pack entry config.
//
// It deliberately does NOT re-parse what fleet-config.mjs already owns (owner,
// exclude, canonRepo, staleDays, packSeeds). The digest reads those through that
// module; this one covers only the block canon knows nothing about:
//
//   { "id": "sheepdog", "config": { "digest": {
//       "pick":  4,                       // how many accomplishments the brief names
//       "nudge": { "enabled": true, "quietDays": 7 }
//   } } }
//
// TWO KEYS, AND NOTHING ABOUT DELIVERY. The task finishes at a written report; an
// ad-hoc session reads that file out later in the day and its own notification
// mechanism carries it. So there is no recipient, no sender and no transport to
// configure here — a knob for any of them would describe machinery this repo does
// not own.
//
// Both keys default, and an absent `digest` block is a valid one — a fleet that
// configures nothing still gets its dated file. That is the same stance fleet-config
// takes on its own optional knobs, and it is what lets this pack be adopted without
// an interview.

// How many accomplishments the brief names. Four is the number the owner's own daily
// routine settled on: enough that a busy day is represented, few enough that the
// brief stays skimmable.
export const DEFAULT_PICK = 4;

// How much MORE than `pick` the shortlist carries. The agent's judgment is the point
// of the task — handing it exactly `pick` candidates would leave it nothing to judge,
// since the deterministic size ranking would have made every choice already. Half
// again gives it a real choice (6 for the default 4) while keeping the read bounded.
export const OVERFETCH = 1.5;

// How long a project must have gone without a MEANINGFUL change before the brief
// prods about it. A week is the owner's framing ("no meaningful changes in the last
// week"); a fleet whose projects legitimately idle longer raises it rather than
// living with a nudge that fires on everything.
export const DEFAULT_QUIET_DAYS = 7;

// Bound `pick` at both ends. The brief is a brief: a `pick` of 40 is not a
// configuration, it is a mistake that would dispatch an agent to read forty PRs.
const MAX_PICK = 10;

const positiveInt = (v, fallback, max) => {
  const n = Number(v);
  if (!Number.isFinite(n) || n < 1) return fallback;
  return Math.min(Math.floor(n), max);
};

// The nudge — "prod me about a project I have not touched" — is a whole FEATURE of
// the brief, not a formatting detail, so it is switchable as one:
//
//   absent            → on, at the default window (the useful default)
//   false             → off entirely; the brief carries accomplishments only
//   true              → on, at the default window
//   { quietDays: 14 } → on, at that window
//   { enabled: false } → off (the long form of `false`)
//
// Both spellings of off exist because both get written: `"nudge": false` is what
// someone reaches for when switching it off, and `{ "enabled": false }` is what they
// reach for when they already have a `quietDays` they want to keep.
export function parseNudge(raw) {
  if (raw === false) return { enabled: false, quietDays: DEFAULT_QUIET_DAYS };
  if (raw === true || raw === undefined || raw === null) {
    return { enabled: true, quietDays: DEFAULT_QUIET_DAYS };
  }
  if (typeof raw !== 'object' || Array.isArray(raw)) {
    // A number, a string, anything else: unreadable, so fall back to the default
    // rather than guessing which half of it was meant.
    return { enabled: true, quietDays: DEFAULT_QUIET_DAYS };
  }
  return {
    enabled: raw.enabled !== false,
    quietDays: positiveInt(raw.quietDays, DEFAULT_QUIET_DAYS, 365),
  };
}

// Parse the `digest` block off an already-parsed `.claudinite-checks.json`. Pure —
// no I/O, no defaults read from the environment — so the task and its tests see
// exactly the same resolution.
export function parseDigestConfig(cfg) {
  const entry = (Array.isArray(cfg?.packs) ? cfg.packs : []).find((e) => e?.id === 'sheepdog');
  const raw = entry?.config?.digest;
  const d = raw && typeof raw === 'object' && !Array.isArray(raw) ? raw : {};

  const pick = positiveInt(d.pick, DEFAULT_PICK, MAX_PICK);

  return {
    pick,
    // Derived, never configured directly: the overfetch is a property of how the task
    // works (give the agent a real choice), not a knob a fleet has an opinion about.
    shortlist: Math.ceil(pick * OVERFETCH),
    nudge: parseNudge(d.nudge),
  };
}
########## digest-plain-text.mjs ##########
import { finding } from '../../../shared/engine/checks/helpers/findings.mjs';

// The brief is DELIVERED, not read on GitHub. An ad-hoc session reads `digests/<date>.md`
// and sends it as a notification verbatim (digests/README.md, "Getting it read"), and the
// notification renderer that carries it does two things this rule exists for:
//
//   IT DOES NOT PARSE MARKDOWN. `#`, `##`, `-`, `**bold**`, backticks and `[#750](url)`
//   all arrive as literal characters, so a brief written in markdown reaches the owner as
//   its own source code.
//   IT COLLAPSES WHITESPACE. Every newline and blank line is gone — four bullets and two
//   sections arrive as one running paragraph — so nothing structural may depend on a line
//   break surviving.
//
// Together those make markdown strictly worse than plain text here: the syntax costs the
// reader attention and buys the structure it normally pays for exactly nowhere. So the
// brief is plain text that reads correctly collapsed — a "• " opening each item is the
// separator that survives, and a bare URL is left bare because the renderer autolinks it.
//
// Scope is the dated briefs only. `digests/README.md` is documentation about the series,
// is read on GitHub, is never sent, and is markdown on purpose.
//
// BLOCKING: an unreadable brief is the task's entire output failing, and it fails silently
// — the file is well-formed, the run is green, and only the owner's inbox shows it.
const BRIEF = /^digests\/\d{4}-\d\d-\d\d\.md$/;

// Each syntax the renderer shows raw, with the plain-text form that replaces it. Ordered
// as a reader meets them; the fix text names the replacement so a finding is actionable
// without opening this file.
const SYNTAX = [
  { what: 'an ATX heading', re: /^ {0,3}#{1,6}\s/, fix: 'a bare line of text' },
  { what: 'a list bullet', re: /^ {0,3}[-*+]\s/, fix: '"• ", which stays a visible separator once the newlines collapse' },
  { what: 'an inline link', re: /\[[^\]\n]*\]\([^)\n]*\)/, fix: 'the bare URL at the end of the item — the renderer autolinks it' },
  { what: 'asterisk emphasis', re: /\*/, fix: 'nothing; the words carry it' },
  { what: 'a backtick', re: /`/, fix: 'plain text, or double quotes where a quotation is genuinely needed' },
  { what: 'underscore emphasis', re: /(^|\s)_[^_\s][^_\n]*_(?=$|[\s.,;:)])/, fix: 'nothing; the words carry it' },
];

const rule = {
  id: 'digest-plain-text',
  severity: 'blocking',
  description: 'every dated brief under digests/ is plain text — no markdown syntax the notification renderer would show raw',
  doc: '.claudinite/local/packs/sheepdog-local/digest-plain-text.mjs',
  why: 'the brief is sent verbatim through a renderer that neither parses markdown nor keeps line breaks, so any markdown in it reaches the owner as literal characters in one running paragraph',

  run(ctx) {
    const out = [];
    for (const file of ctx.allFiles) {
      if (!BRIEF.test(file)) continue;
      const text = ctx.read(file);
      if (text === null) continue;

      // First offence per syntax, and the earliest line among them — one finding per
      // file, pointing at the first place the reader would see it break.
      const lines = text.split('\n');
      const hits = [];
      for (const s of SYNTAX) {
        const i = lines.findIndex((l) => s.re.test(l));
        if (i !== -1) hits.push({ ...s, line: i + 1 });
      }
      if (hits.length === 0) continue;

      hits.sort((a, b) => a.line - b.line);
      out.push(finding(rule, {
        file,
        line: hits[0].line,
        what: `contains ${hits.map((h) => `${h.what} (line ${h.line})`).join(', ')} — the renderer shows each of these raw`,
        fix: hits.map((h) => `replace ${h.what} with ${h.fix}`).join('; '),
      }));
    }
    return out;
  },
};

export default rule;
########## dated-fixture-collision.mjs ##########
import { finding } from '../../../shared/engine/checks/helpers/findings.mjs';

// Learned from #130, which `reference-integrity` surfaced only by accident. `worker.test.mjs`
// asserted on a `digests/2026-08-…md` path, #127 deleted that brief, and the dangling string
// went red. The dangling reference was the symptom; the defect is that the fixture drew its
// dates from the window the fleet is actually running in, so the paths those assertions build
// share a namespace with real dated artifacts.
//
// That sharing is the whole problem, and it cuts both ways. The failing direction is loud and
// got caught: delete the brief and the assertion breaks. The passing direction is silent and
// would not have been — had a real brief existed at the asserted path, the test would have gone
// green for a reason that has nothing to do with the code under test. A test written that way
// has stopped testing `planBriefs` and started testing repo state.
//
// This repo writes a new dated artifact under `digests/` every single morning, so the namespace
// it collides with grows daily and no fixture date in the 2000s is safe for long. A year the
// fleet will never have briefs for cannot collide in either direction.
//
// A check rather than prose: "a test file contains a `digests/<20xx date>` literal" is a static
// signature a post-hoc scan reads straight off the artifact.
//
// BLOCKING, because the silent direction is a test that passes for the wrong reason — the kind
// of green that hides a regression rather than an expected transient. Unlike managed-workflow-drift
// there is no normal window in which a real-dated fixture is correct.
//
// Scope is this repo's own test files. `.claudinite/shared/` is the read-only canon mount, and
// nothing here may hold it to a rule this repo learned about its OWN dated artifacts.
const ARTIFACT_DIR = 'digests/';
const MOUNT = '.claudinite/shared/';

// `digests/` followed by a date whose year is 2000-2099 — the range the fleet actually runs in
// and therefore the only range that can collide with a real brief. 1999 (or any non-20xx year)
// is exactly the escape this rule steers toward, so it must not match.
const COLLIDING = /digests\/(20\d\d-\d\d-\d\d)/g;

const rule = {
  id: 'dated-fixture-collision',
  severity: 'blocking',
  description: 'no test fixture builds a digests/ path in the year range the fleet writes real briefs in',
  doc: '.claudinite/local/packs/sheepdog-local/dated-fixture-collision.mjs',
  why: 'a fixture sharing a namespace with real dated artifacts has started depending on repo state — it breaks when a brief is deleted, and passes for the wrong reason when one happens to exist',

  run(ctx) {
    const out = [];
    for (const file of ctx.allFiles) {
      if (!file.endsWith('.test.mjs')) continue;
      if (file.startsWith(MOUNT)) continue; // read-only canon, not this repo's to police
      const text = ctx.read(file);
      if (text === null || !text.includes(ARTIFACT_DIR)) continue;

      const hits = [...new Set([...text.matchAll(COLLIDING)].map((m) => m[1]))];
      if (hits.length === 0) continue;
      out.push(finding(rule, {
        file,
        what: `builds ${ARTIFACT_DIR} fixture path(s) dated ${hits.join(', ')} — the years the fleet writes real briefs in`,
        fix: 'move the fixture dates to a year the fleet will never have briefs for (the existing fixtures use 1999) so the asserted paths cannot collide with a real brief in either direction',
      }));
    }
    return out;
  },
};

export default rule;
