const LEAD_IN = /\*\*([\s\S]+?)\*\*/;

const wordsIn = (lines) => lines.join('\n').split(/\s+/).filter(Boolean).length;

const trimTrailingBlanks = (lines) => {
  const out = [...lines];
  while (out.length && !out.at(-1).trim()) out.pop();
