cd /workspace/claudinite && python3 - <<'PY'
import subprocess, re

path='packs/sheepdog/RULES.md'
diff = subprocess.run(['git','diff','origin/main','--',path],capture_output=True,text=True).stdout
added = set(l[1:] for l in diff.split('\n') if l.startswith('+') and not l.startswith('+++'))

lines = open(path).read().split('\n')
out=[]
i=0
def bl(s): return len(s.encode())

while i < len(lines):
    line = lines[i]
    if line in added and bl(line) > 100:
        # gather the contiguous run of added paragraph lines
        para=[]
        while i < len(lines) and lines[i].strip() and lines[i] in added:
            para.append(lines[i]); i+=1
        text = ' '.join(x.strip() for x in para)
        # greedy rewrap to <=100 BYTES, never splitting inside a markdown link
        tokens=[]
        buf=''
        depth=0
        for ch in text:
            buf+=ch
            if ch=='[': depth+=1
            elif ch==']': depth=max(0,depth-1)
            elif ch=='(' and buf.rstrip().endswith('('): pass
            if ch==' ' and depth==0 and not re.search(r'\]\($', buf[:-1]) and '](' not in buf[buf.rfind(' ',0,len(buf)-2)+1:] :
                tokens.append(buf[:-1]); buf=''
        if buf: tokens.append(buf)
        # simpler: split on spaces but glue markdown links back together
        toks = text.split(' ')
        glued=[]
        for t in toks:
            if glued and (glued[-1].count('[') > glued[-1].count(']') or re.search(r'\]\([^)]*$', glued[-1])):
                glued[-1] += ' ' + t
            else:
                glued.append(t)
        cur=''
        for t in glued:
            cand = t if not cur else cur+' '+t
            if bl(cand) > 100 and cur:
                out.append(cur); cur=t
            else:
                cur=cand
        if cur: out.append(cur)
    else:
        out.append(line); i+=1

open(path,'w').write('\n'.join(out))
print('rewrapped')
