  for (const pack of packs.filter((p) => !p.local)) {
    const checks = [...(pack.worldRules ?? []), ...(pack.workRules ?? []), ...(pack.skillChecks ?? [])];
    if (!checks.length) continue;
    const readme = join(ROOT, 'packs', pack.id, 'README.md');
